import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import {render,SERVICES} from '../../scripts/deploy/release.mjs';
const revision=process.argv[2],api='https://ko-card-game.onrender.com',front='https://ko-card-game-vr69.onrender.com';assert.match(revision,/^[a-f0-9]{40}$/);const checks=[];
for(const [role,id]of Object.entries(SERVICES)){const live=(await render(`services/${id}/deploys?limit=5`)).find(x=>x.deploy.status==='live')?.deploy;assert.equal(live?.commit?.id,revision);checks.push({role,revision,deployId:live.id});}
const health=await fetch(api+'/api/healthz').then(r=>r.json());assert.equal(health.revision,revision);const cards=await fetch(api+'/api/cards').then(r=>r.json());assert.ok(cards.cards.length);assert.ok(cards.cards.every(c=>typeof c.lore==='string'));checks.push({publicCards:cards.cards.length,loreFieldPresentOnAll:true});
const cookie=(await readFile('/tmp/ko-latest-balance/admin-cookie.txt','utf8')).trim();for(const path of ['/api/admin/cards','/api/collection','/api/decks/options']){const r=await fetch(api+path,{headers:{Cookie:cookie}});assert.equal(r.status,200);const x=await r.json();assert.ok(x.cards.length);assert.ok(x.cards.every(c=>typeof c.lore==='string'));checks.push({path,cards:x.cards.length,loreFieldPresentOnAll:true});}
assert.equal((await fetch(front+'/version.json',{cache:'no-store'}).then(r=>r.json())).revision,revision);for(const path of ['/','/online/match/lore-release-'+revision.slice(0,12)]){const html=await fetch(front+path,{cache:'no-store'}).then(r=>r.text());const entry=html.match(/<script[^>]+type="module"[^>]+src="([^"]+)"/)?.[1];assert.ok(entry);assert.ok((await fetch(new URL(entry,front)).then(r=>r.text())).includes(revision));checks.push({path,entry,revisionMatches:true});}
const receipt={checkedAt:new Date().toISOString(),revision,checks,productionCardContentWrites:0,productionCombatActions:0};await writeFile('docs/qa/20261113-card-lore/production-release.json',JSON.stringify(receipt,null,2));console.log(JSON.stringify(receipt));
